-- Tracker: eigen versleepbare tracker; volgen activeert watch en supertrack samen.
local NS=QuestSync
function NS.Track(id,on) if not id or NS.IsPrivate(id) then return end; if on then local ok=C_QuestLog.AddQuestWatch(id); if ok==false then NS.Toast("De gevolgde-questlijst is vol."); return end; C_SuperTrack.SetSuperTrackedQuestID(id) else C_QuestLog.RemoveQuestWatch(id) end; C_QuestLog.SortQuestWatches(); NS.RefreshQuests() end
function NS.BuildTracker() if NS.tracker then return end; local f=NS.Panel(UIParent,280,46); f:SetPoint("TOPRIGHT",UIParent,"TOPRIGHT",-22,-190); f:SetMovable(true); f:EnableMouse(true); f:RegisterForDrag("LeftButton"); f:SetScript("OnDragStart",f.StartMoving); f:SetScript("OnDragStop",f.StopMovingOrSizing); local h=NS.Button(f,"QuestSync — doelen",260,function() f.collapsed=not f.collapsed; NS.RefreshTracker() end); h:SetPoint("TOP",0,-7); f.rows={}; NS.tracker=f; NS.RefreshTracker() end
function NS.RefreshTracker() if not NS.tracker then return end; local f=NS.tracker; for _,r in ipairs(f.rows) do r:Hide() end; f.rows={}; if f.collapsed then f:SetHeight(42); return end; local y=-40; for id,q in pairs(NS.quests) do if q.watch then local r=NS.Panel(f,258,48); r:SetPoint("TOP",0,y); local b=NS.Button(r,q.title,238,function() NS.OpenQuest(id) end); b:SetPoint("TOP",0,-2); if q.complete then b.text:SetTextColor(.3,.9,.4) end; b:SetScript("OnMouseUp",function(_,button) if button=="RightButton" then NS.Track(id,false) end end); if q.private then local l=NS.Label(r,"persoonlijk",12); l:SetPoint("BOTTOMLEFT",8,3) else for i,o in ipairs(q.objectives) do local l=NS.Label(r,(o.text or "Doel").."  "..o.numFulfilled.."/"..o.numRequired,12); l:SetPoint("BOTTOMLEFT",8,3+(i-1)*14); if o.finished then l:SetTextColor(.3,.85,.35) end end end; f.rows[#f.rows+1]=r; y=y-52 end end; f:SetHeight(math.max(50,-y+5)) end
local f=CreateFrame("Frame"); f:RegisterEvent("PLAYER_LOGIN"); f:SetScript("OnEvent",function() if ObjectiveTrackerFrame then ObjectiveTrackerFrame:Hide(); ObjectiveTrackerFrame:HookScript("OnShow",function(self) self:Hide() end) end; NS.BuildTracker() end)
